// The version at the foot of the gallery's page (COMMON-PROJECT-SPEC, C13:
// a repo that serves a page shows which build it runs, read from package.json
// at build time). The gallery's page is generated by the sketch-gallery
// package, so, like the tracker (inject-umami.js), the line is written into
// the built folder after the build and before the deploy
// (.github/workflows/deploy-github-pages.yaml).
//
// Only the root index.html gets it: the sketch pages are the artwork, drawn
// full screen, and nothing is laid over them.
//
//   node scripts/inject-version.js <dist folder>
//
// The line is a <footer> before </body>, in the flow after the gallery —
// not fixed, because the page already pins its social links to the bottom
// edge — linking to the repository's releases. Idempotent: a page already
// carrying the marker is left alone, so the script can run twice without
// harm.

const { readFileSync, writeFileSync } = require("node:fs");
const { join, resolve } = require("node:path");

const MARKER = 'data-version="';
const RELEASES = "https://github.com/CostardRouge/generative-art-p5js/releases";

function escapeHtml(value) {
  return String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/"/g, "&quot;");
}

// The social bar is fixed at the bottom edge and about 64 px tall: the padding
// keeps the line readable above it once the page is scrolled to its end.
function footer(version) {
  const v = escapeHtml(version);
  return (
    `<footer data-version="${v}" style="padding:0 12px 80px;text-align:right;font-size:.75rem;opacity:.6">` +
    `<a href="${RELEASES}" style="color:inherit" rel="noopener">v${v}</a></footer>`
  );
}

// Inserts the footer before </body> (the first one, any case); a page without
// a body, or one that already carries the footer, is left alone.
function inject(html, version) {
  if (html.includes(MARKER)) return null;
  const at = html.search(/<\/body\s*>/i);
  if (at < 0) return null;
  return `${html.slice(0, at)}${footer(version)}\n${html.slice(at)}`;
}

function main() {
  const dir = process.argv[2];
  if (!dir) {
    console.error("usage: node scripts/inject-version.js <dist folder>");
    process.exit(1);
  }
  const { version } = JSON.parse(readFileSync(resolve(__dirname, "../package.json"), "utf8"));
  if (!version) {
    console.error("inject-version: package.json carries no version.");
    process.exit(1);
  }
  const file = join(dir, "index.html");
  const next = inject(readFileSync(file, "utf8"), version);
  if (next === null) {
    console.log(`inject-version: ${file} left alone (no body, or the version is already there).`);
    return;
  }
  writeFileSync(file, next);
  console.log(`inject-version: v${version} written into ${file}.`);
}

if (require.main === module) main();

module.exports = { inject, footer };
